<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();fleet_cert_require_same_origin_post();$db=fleet_db();$actor=(int)$user['id'];$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in))json_response(['ok'=>false,'message'=>'Invalid trip request.'],400);
function trip_ready(PDO $db,int $horse,int $trailer,int $driver): array|false
{
 $sql="SELECT r.id,r.attachment_id,r.driver_assignment_id,r.horse_inspection_id,r.trailer_inspection_id,r.driver_fitness_check_id FROM combination_readiness_approvals r JOIN asset_attachments aa ON aa.id=r.attachment_id AND aa.head_asset_id=? AND aa.trailer_asset_id=? AND aa.attached_to IS NULL JOIN asset_driver_assignments da ON da.id=r.driver_assignment_id AND da.asset_id=? AND da.driver_id=? AND da.assigned_to IS NULL JOIN vehicle_inspections hi ON hi.id=r.horse_inspection_id AND hi.asset_id=? AND hi.result='PASS' AND hi.critical_defects=0 AND hi.checked_at>=NOW()-INTERVAL 24 HOUR JOIN vehicle_inspections ti ON ti.id=r.trailer_inspection_id AND ti.asset_id=? AND ti.result='PASS' AND ti.critical_defects=0 AND ti.checked_at>=NOW()-INTERVAL 24 HOUR JOIN driver_fitness_checks fc ON fc.id=r.driver_fitness_check_id AND fc.driver_id=? AND fc.result='PASS' AND fc.licence_checked=1 AND fc.licence_expiry>=CURDATE() AND fc.rested=1 AND fc.fit_to_drive=1 AND fc.checked_at>=NOW()-INTERVAL 24 HOUR JOIN drivers d ON d.id=da.driver_id AND d.is_active=1 JOIN assets h ON h.id=aa.head_asset_id AND h.is_active=1 JOIN assets t ON t.id=aa.trailer_asset_id AND t.is_active=1 WHERE r.horse_asset_id=? AND r.trailer_asset_id=? AND r.driver_id=? AND r.status='APPROVED' AND r.horse_inspection_id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=?) AND r.trailer_inspection_id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=?) AND r.driver_fitness_check_id=(SELECT MAX(id) FROM driver_fitness_checks WHERE driver_id=?) AND NOT EXISTS(SELECT 1 FROM maintenance_logs ml WHERE ml.asset_id IN (?,?) AND ml.resolved_at IS NULL) AND NOT EXISTS(SELECT 1 FROM maintenance_work_orders mw WHERE mw.asset_id IN (?,?) AND mw.status IN ('OPEN','IN_PROGRESS','REPAIR_COMPLETE')) ORDER BY r.id DESC LIMIT 1";
 $q=$db->prepare($sql);$q->execute([$horse,$trailer,$horse,$driver,$horse,$trailer,$driver,$horse,$trailer,$driver,$horse,$trailer,$driver,$horse,$trailer,$horse,$trailer]);return $q->fetch();
}
try{$action=(string)($in['action']??'');if($action==='create_trip')fleet_cert_require_permission($user,'trips.request');elseif($action==='decide_trip')fleet_cert_require_permission($user,'trips.approve');elseif($action==='trip_status')fleet_cert_require_permission($user,'trips.manage');$db->beginTransaction();
 if($action==='create_trip'){
  $horse=(int)($in['horse_asset_id']??0);$trailer=(int)($in['trailer_asset_id']??0);$driver=(int)($in['driver_id']??0);if(!$horse||!$trailer||!$driver)throw new InvalidArgumentException('Select a ready Horse, linked Trailer, and assigned Driver.');$q=$db->prepare("SELECT trip_number FROM fleet_trips WHERE status='PENDING' AND (horse_asset_id=? OR trailer_asset_id=? OR driver_id=?) ORDER BY requested_at DESC,id DESC LIMIT 1 FOR UPDATE");$q->execute([$horse,$trailer,$driver]);$pendingTrip=$q->fetchColumn();if($pendingTrip)throw new InvalidArgumentException('Trip '.$pendingTrip.' already has this Horse, Trailer, or driver under review. Wait for the reviewer to decide it before submitting another trip.');if(!trip_ready($db,$horse,$trailer,$driver))throw new InvalidArgumentException('This combination is not currently approved as ready. Complete current inspections and request readiness approval first.');$q=$db->prepare("SELECT id FROM fleet_trips WHERE status IN ('APPROVED','IN_PROGRESS') AND (horse_asset_id=? OR trailer_asset_id=? OR driver_id=?) LIMIT 1 FOR UPDATE");$q->execute([$horse,$trailer,$driver]);if($q->fetchColumn())throw new InvalidArgumentException('This Horse, Trailer, or driver is already assigned to an approved or active trip. Complete or cancel that trip first.');
  $customer=trim((string)($in['customer_name']??''));$pickup=trim((string)($in['pickup_location']??''));$destination=trim((string)($in['destination']??''));$cargo=trim((string)($in['cargo_description']??''));foreach(['customer'=>$customer,'pickup'=>$pickup,'destination'=>$destination,'cargo'=>$cargo] as $key=>$value){$max=$key==='customer'?180:($key==='cargo'?500:180);if($value===''||mb_strlen($value)>$max)throw new InvalidArgumentException('Enter a valid customer, pickup, destination, and cargo description.');}
  $departure=DateTimeImmutable::createFromFormat('Y-m-d\TH:i',(string)($in['scheduled_departure']??''));if(!$departure)throw new InvalidArgumentException('Enter a valid planned departure date and time.');$returnRaw=trim((string)($in['expected_return']??''));$return=$returnRaw===''?null:DateTimeImmutable::createFromFormat('Y-m-d\TH:i',$returnRaw);if($returnRaw!==''&&!$return)throw new InvalidArgumentException('Enter a valid expected return date and time.');if($return&&$return<$departure)throw new InvalidArgumentException('Expected return must be after departure.');
  $qty=trim((string)($in['cargo_quantity']??''));$qty=$qty===''?null:filter_var($qty,FILTER_VALIDATE_FLOAT);if($qty!==null&&($qty===false||$qty<0))throw new InvalidArgumentException('Enter a valid cargo quantity.');$values=[];foreach(['customer_address'=>500,'cargo_unit'=>30,'request_reason'=>500] as $k=>$max){$values[$k]=trim((string)($in[$k]??''));if(mb_strlen($values[$k])>$max)throw new InvalidArgumentException('One of the trip details is too long.');}$odoRaw=trim((string)($in['odometer_start']??''));$odo=$odoRaw===''?null:filter_var($odoRaw,FILTER_VALIDATE_INT);if($odoRaw!==''&&$odo===false)throw new InvalidArgumentException('Enter a valid departure odometer.');
  $number='TR-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$db->prepare('INSERT INTO fleet_trips(trip_number,status,horse_asset_id,trailer_asset_id,driver_id,customer_name,customer_address,pickup_location,destination,cargo_description,cargo_quantity,cargo_unit,scheduled_departure,expected_return,odometer_start,request_reason,requested_by) VALUES(?,\'PENDING\',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$number,$horse,$trailer,$driver,$customer,$values['customer_address']?:null,$pickup,$destination,$cargo,$qty,$values['cargo_unit']?:null,$departure->format('Y-m-d H:i:s'),$return?$return->format('Y-m-d H:i:s'):null,$odo,$values['request_reason']?:null,$actor]);$id=(int)$db->lastInsertId();fleet_cert_log($db,$actor,'REQUEST','FLEET_TRIP',$id,'Submitted trip '.$number.' for approval.');$db->commit();json_response(['ok'=>true,'message'=>'Trip submitted for approval.','trip_number'=>$number]);
 }
 if($action==='decide_trip'){
  $id=(int)($in['trip_id']??0);$decision=strtoupper(trim((string)($in['decision']??'')));$reason=trim((string)($in['reason']??''));if(!$id||!in_array($decision,['APPROVED','DECLINED'],true))throw new InvalidArgumentException('Choose a valid trip decision.');if($decision==='DECLINED'&&$reason==='')throw new InvalidArgumentException('A reason is required when declining a trip.');if(mb_strlen($reason)>500)throw new InvalidArgumentException('The decision reason is too long.');$q=$db->prepare('SELECT * FROM fleet_trips WHERE id=? FOR UPDATE');$q->execute([$id]);$trip=$q->fetch();if(!$trip||$trip['status']!=='PENDING')throw new InvalidArgumentException('This trip is no longer pending review.');if((int)$trip['requested_by']===$actor)throw new InvalidArgumentException('A different reviewer must decide this trip.');if($decision==='APPROVED'&&!trip_ready($db,(int)$trip['horse_asset_id'],(int)$trip['trailer_asset_id'],(int)$trip['driver_id']))throw new InvalidArgumentException('The Full Truck readiness approval is no longer valid. Refresh the inspections and submit a new trip.');$status=$decision;$q=$db->prepare('UPDATE fleet_trips SET status=?,decided_by=?,decided_at=NOW(),decision_reason=? WHERE id=? AND status=\'PENDING\'');$q->execute([$status,$actor,$reason?:null,$id]);fleet_cert_log($db,$actor,$decision,'FLEET_TRIP',$id,($decision==='APPROVED'?'Approved trip ':'Declined trip ').$trip['trip_number'].($reason?' · '.$reason:''));$db->commit();json_response(['ok'=>true,'message'=>$decision==='APPROVED'?'Trip approved. It is ready for dispatch; financial invoicing belongs in SAP Business One.':'Trip declined.']);
 }
 if($action==='trip_status'){
  $id=(int)($in['trip_id']??0);$status=strtoupper(trim((string)($in['status']??'')));if(!$id||!in_array($status,['IN_PROGRESS','COMPLETED'],true))throw new InvalidArgumentException('Choose Dispatch or Complete.');$q=$db->prepare('SELECT * FROM fleet_trips WHERE id=? FOR UPDATE');$q->execute([$id]);$trip=$q->fetch();if(!$trip)throw new InvalidArgumentException('Trip not found.');
  if($status==='IN_PROGRESS'){
   if($trip['status']!=='APPROVED')throw new InvalidArgumentException('Only an approved trip can be dispatched.');
   $q=$db->prepare("SELECT id FROM fleet_trips WHERE id<>? AND status IN ('APPROVED','IN_PROGRESS') AND (horse_asset_id=? OR trailer_asset_id=? OR driver_id=?) LIMIT 1 FOR UPDATE");$q->execute([$id,(int)$trip['horse_asset_id'],(int)$trip['trailer_asset_id'],(int)$trip['driver_id']]);if($q->fetchColumn())throw new InvalidArgumentException('This Horse, Trailer, or driver is already assigned to another approved or active trip.');
   if(!trip_ready($db,(int)$trip['horse_asset_id'],(int)$trip['trailer_asset_id'],(int)$trip['driver_id']))throw new InvalidArgumentException('Readiness is no longer current. Do not dispatch until the Full Truck is checked and approved again.');
   $q=$db->prepare("UPDATE fleet_trips SET status='IN_PROGRESS',dispatched_at=NOW() WHERE id=? AND status='APPROVED'");$q->execute([$id]);
  } else {
   if($trip['status']!=='IN_PROGRESS')throw new InvalidArgumentException('Only a dispatched trip can be completed.');
   if(empty($trip['dispatched_at']))throw new InvalidArgumentException('This trip has no dispatch time recorded. Contact an administrator before completing it.');
   $q=$db->prepare('SELECT TIMESTAMPDIFF(SECOND,?,NOW())');$q->execute([$trip['dispatched_at']]);$elapsed=(int)$q->fetchColumn();if($elapsed<300)throw new InvalidArgumentException('A trip can be completed after it has been dispatched for at least 5 minutes. Please wait '.max(1,(int)ceil((300-$elapsed)/60)).' more minute(s).');
   $odometer=isset($in['odometer_end'])&&$in['odometer_end']!==''?filter_var($in['odometer_end'],FILTER_VALIDATE_INT):null;if((($in['odometer_end']??'')!=='')&&$odometer===false)throw new InvalidArgumentException('Enter a valid ending odometer.');if($odometer!==null&&$trip['odometer_start']!==null&&$odometer<(int)$trip['odometer_start'])throw new InvalidArgumentException('Ending odometer cannot be lower than the departure odometer.');
   $q=$db->prepare("UPDATE fleet_trips SET status='COMPLETED',odometer_end=COALESCE(?,odometer_end),completed_at=NOW() WHERE id=? AND status='IN_PROGRESS'");$q->execute([$odometer,$id]);
  }
  fleet_cert_log($db,$actor,$status==='IN_PROGRESS'?'DISPATCH':'COMPLETE','FLEET_TRIP',$id,($status==='IN_PROGRESS'?'Dispatched trip ':'Completed trip ').$trip['trip_number'].'.');$db->commit();json_response(['ok'=>true,'message'=>$status==='IN_PROGRESS'?'Trip dispatched. Completion will be available after five minutes.':'Trip marked completed.']);
 }
 throw new InvalidArgumentException('Choose a valid trip action.');
}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Trip update: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The trip change could not be saved. No changes were applied.'],500);}
